51:     this._chipMaps.forEach(chipMap => {
52:       chipMap.chips.forEach(chip => {
53:         this.updates.push(
54:           ...this._buildUpdates(chip, chipMap.chipList, 'mat-chip-row', 'mat-chip-option'),
55:         );
56:       });
57:     });
58: 
59:     return this.updates;
60:   }
61: 
62:   override reset(): void {
63:     super.reset();
64:     this._chipInputAttrs = [];
65:     this._chipMaps = [];
66:   }
67: 
68:   private _handleChipListNode(node: compiler.TmplAstElement): void {
69:     this._chipMap = {
70:       chipList: node,
71:       chips: [],
72:     };
73: 
