99:    * to become a mat-chip-grid or a mat-chip-listbox.
100:    *
101:    * @param node The node to update.
102:    * @param chipListNode The node to evaluate as either a grid or listbox.
103:    * @param gridTag The new tag name if the chipListNode is a grid.
104:    * @param listboxTag The new tag name if the chipListNode is a listbox.
105:    * @returns The start and end tag updates for the given node.
106:    */
107:   private _buildUpdates(
108:     node: compiler.TmplAstElement,
109:     chipListNode: compiler.TmplAstElement,
110:     gridTag: string,
111:     listboxTag: string,
112:   ): Update[] {
113:     return [
114:       {
