119:             : replaceStartTag(html, node, listboxTag);
120:         },
121:       },
122:       {
123:         location: node.endSourceSpan!.start,
124:         updateFn: html => {
125:           return this._isChipGrid(chipListNode)
126:             ? replaceEndTag(html, node, gridTag)
127:             : replaceEndTag(html, node, listboxTag);
128:         },
129:       },
130:     ];
131:   }
132: 
133:   /** Stores the matChipInputFor references on given input. */
134:   private _storeChipRefs(node: compiler.TmplAstElement): void {
135:     for (let i = 0; i < node.inputs.length; i++) {
136:       if (node.inputs[i].name === 'matChipInputFor') {
137:         this._chipInputAttrs.push(node.inputs[i]);
138:         return;
139:       }
140:     }
141:   }
