143:   /**
144:    * Returns whether the given node should be a mat-chip-grid or mat-chip-listbox.
145:    *
146:    * This is determined by whether the given mat-chip-list is referenced by any inputs. If it is,
147:    * then the node is a mat-chip-grid. Otherwise, it is a mat-chip-listbox.
148:    *
149:    * IMPORTANT: This function should only be used in an updateFn callback. This function assumes
150:    * the entire tree has already been traversed and all matChipInputFor attributes have been
151:    * found and stored.
152:    */
153:   private _isChipGrid(node: compiler.TmplAstElement): boolean {
154:     return node.references.some(ref => {
155:       return this._chipInputAttrs.some(attr => {
156:         const value = attr.value as compiler.ASTWithSource;
157:         return value.source === ref.name;
158:       });
159:     });
160:   }
161: }

